"""Build the independent, beginner-appropriate Part I proposal only."""
from pathlib import Path
import json, shutil, hashlib

ROOT = Path(__file__).resolve().parents[1]
archive = ROOT / 'qa' / 'before-readable-revision'
archive.mkdir(exist_ok=True)
for name in ['OrgResource-Concise-Submission-Proposal.md', 'OrgResource-Concise-Submission-Proposal.docx']:
    if not (archive / name).exists():
        shutil.copy2(ROOT / name, archive / name)
full_hash = hashlib.sha256((ROOT / 'OrgResource-Formal-Proposal.docx').read_bytes()).hexdigest()

parts = []
def p(s=''):
    parts.append(s.strip() + '\n')
def code(value):
    p('```json\n' + json.dumps(value, indent=2, ensure_ascii=False) + '\n```')
def operation(title, verb, url, inputs, output, method, errors):
    p('#### ' + title)
    p(f'**URL:** {verb} {url}')
    p('**Input:** ' + inputs)
    p('**Output:** ' + output)
    p('**Forward to:** ' + method + '.')
    p('**Errors:** ' + errors)

p('# OrgResource Project Proposal')
p('Student Organization Resource Planning and Allocation System')
p('**Group member:** Ethan Owen Taruc — 236196')
p('OrgResource will help a student organization record its resources, list what each project needs, and allocate available supplies or equipment. Officers will record items issued, reusable items returned, and consumables used. A scheduled SMS reminder will help borrowers return equipment on time. This document describes the proposed design; implementation and testing are still to be done.')
p('The design uses five entities: Department, Project, Resource, ResourceRequirement, and Allocation. A requirement records a project’s need; an allocation records the quantity assigned to meet it. Quantities are whole numbers, and each allocation is issued, returned, or consumed as one batch.')

p('## Controller operations')
p('Each controller will receive the request and forward it through @Autowired to its component. All URLs below start with http://localhost:8080. Inputs named in an operation are required unless marked optional. POST inputs go in a JSON body; values in {braces} go in the URL. GET filters go after the URL, for example /api/requirements?projectId=1.')
p('Create operations return 201. Other successful operations return 200. List operations return a JSON array, or [] when nothing matches. Record formats appear under each controller. Example IDs identify sample records; actual IDs will be generated by the database. Related records are shown by ID rather than repeated inside the response.')

p('### Shared error format')
p('Errors will return the appropriate HTTP status and a short message, for example:')
code({'message': 'Resource not found.'})
p('All operations may return 400 for invalid input or 500 with “The request could not be completed.” For an invalid field, the message will identify the problem, such as “quantity must be greater than zero.” A missing record named by a URL or input ID returns 404 with “[Entity] not found.” The operation descriptions below give the other expected errors. An unsuccessful operation will not save a partial change.')

p('### DepartmentController')
p('Department JSON format:')
code({'id': 1, 'name': 'Logistics'})
operation('Create department', 'POST', '/api/departments', 'name.', 'The new Department JSON.', 'DepartmentComponent.create(name)', '409: “Department name already exists.”')
operation('List departments', 'GET', '/api/departments', 'None.', 'An array of Department JSON records.', 'DepartmentComponent.list()', 'Shared errors only.')
operation('Update department', 'POST', '/api/departments/{id}/update', 'Department id in the URL; name in the body.', 'The updated Department JSON.', 'DepartmentComponent.update(id, name)', '409: “Department name already exists.”')
operation('Delete department', 'POST', '/api/departments/{id}/delete', 'Department id in the URL; no body.', 'The deletion message shown below.', 'DepartmentComponent.delete(id)', '409: “Department still has projects.”')
p('All successful delete operations use this JSON format:')
code({'message': 'Record deleted.'})

p('### ProjectController')
p('Project JSON format. Dates use Philippine local time in YYYY-MM-DDTHH:mm:ss format.')
code({'id': 1, 'departmentId': 1, 'name': 'Welcome Workshop', 'startAt': '2026-11-10T09:00:00', 'endAt': '2026-11-10T12:00:00'})
operation('Create project', 'POST', '/api/projects', 'departmentId, name, startAt, endAt.', 'The new Project JSON.', 'ProjectComponent.create(departmentId, name, startAt, endAt)', '400: “Project must end after it starts.” or “Project start must be in the future.”')
operation('List projects', 'GET', '/api/projects', 'Optional query filter: departmentId.', 'An array of Project JSON records.', 'ProjectComponent.list(departmentId)', 'Shared errors only.')
operation('Update project', 'POST', '/api/projects/{id}/update', 'Project id in the URL; name, startAt, endAt in the body. departmentId stays unchanged.', 'The updated Project JSON.', 'ProjectComponent.update(id, name, startAt, endAt)', '400: the same date errors as create. 409: “Project has approved or completed allocations; its dates cannot change.” Name-only changes remain allowed.')
operation('Delete project', 'POST', '/api/projects/{id}/delete', 'Project id in the URL; no body.', 'The deletion message.', 'ProjectComponent.delete(id)', '409: “Project still has resource requirements.”')

p('### ResourceController')
p('Resource JSON format. totalQuantity means usable items owned for REUSABLE resources, or remaining stock for CONSUMABLE resources. availableQuantity is calculated rather than saved.')
code({'id': 1, 'name': 'Extension cord', 'type': 'REUSABLE', 'totalQuantity': 10, 'availableQuantity': 6})
operation('Create resource', 'POST', '/api/resources', 'name, type, totalQuantity.', 'The new Resource JSON; initially availableQuantity equals totalQuantity.', 'ResourceComponent.create(name, type, totalQuantity)', '409: “Resource name already exists.”')
operation('List resources', 'GET', '/api/resources', 'Optional query filter: type.', 'An array of Resource JSON records, including availableQuantity.', 'ResourceComponent.list(type)', 'Shared errors only.')
operation('Update resource', 'POST', '/api/resources/{id}/update', 'Resource id in the URL; name and totalQuantity in the body. type stays unchanged.', 'The updated Resource JSON.', 'ResourceComponent.update(id, name, totalQuantity)', '409: “Resource name already exists.” or “Quantity cannot be lower than the quantity already reserved or issued.”')
operation('Delete resource', 'POST', '/api/resources/{id}/delete', 'Resource id in the URL; no body.', 'The deletion message.', 'ResourceComponent.delete(id)', '409: “Resource still has project requirements.”')
operation('Check available quantity', 'GET', '/api/resources/{id}/availability', 'Resource id in the URL.', 'The availability JSON below.', 'ResourceComponent.getAvailability(id)', 'Shared errors only.')
code({'resourceId': 1, 'availableQuantity': 6})

p('### RequirementController')
p('ResourceRequirement JSON format. allocatedQuantity counts approved, issued, returned, and consumed allocations. shortageQuantity is the requested quantity minus allocatedQuantity. Pending and cancelled allocations do not cover a requirement.')
code({'id': 1, 'projectId': 1, 'resourceId': 1, 'quantity': 6, 'allocatedQuantity': 4, 'shortageQuantity': 2})
operation('Create requirement', 'POST', '/api/requirements', 'projectId, resourceId, quantity.', 'The new ResourceRequirement JSON; initially allocatedQuantity is 0.', 'RequirementComponent.create(projectId, resourceId, quantity)', '409: “This resource is already listed for the project.” or “Project has already ended.”')
operation('List requirements', 'GET', '/api/requirements', 'Optional query filter: projectId.', 'An array of ResourceRequirement JSON records, including shortages.', 'RequirementComponent.list(projectId)', 'Shared errors only.')
operation('Update requirement quantity', 'POST', '/api/requirements/{id}/update', 'Requirement id in the URL; quantity in the body. Project and resource stay unchanged.', 'The updated ResourceRequirement JSON.', 'RequirementComponent.update(id, quantity)', '409: “Quantity cannot be lower than the quantity already allocated.” or “Project has already ended.”')
operation('Delete requirement', 'POST', '/api/requirements/{id}/delete', 'Requirement id in the URL; no body.', 'The deletion message.', 'RequirementComponent.delete(id)', '409: “Requirement still has allocation records.”')

p('### AllocationController')
p('Allocation JSON format. PENDING means awaiting approval; APPROVED means stock is reserved; ISSUED means reusable items are with the borrower; RETURNED and CONSUMED mean completed; CANCELLED means no stock remains reserved. The component sets status and reminderAttempted.')
code({'id': 1, 'requirementId': 1, 'quantity': 4, 'borrowerName': 'Workshop representative', 'phoneNumber': None, 'smsConsent': False, 'status': 'PENDING', 'reminderAttempted': False})
operation('Create allocation request', 'POST', '/api/allocations', 'requirementId, quantity, borrowerName; optional phoneNumber; optional smsConsent, default false.', 'The new Allocation JSON with status PENDING.', 'AllocationComponent.create(requirementId, quantity, borrowerName, phoneNumber, smsConsent)', '400: “Quantity exceeds the requirement.” or “A valid phone number is required for SMS consent.” 409: “Project has already ended.”')
operation('List allocations', 'GET', '/api/allocations', 'Optional query filters: requirementId and status; when both are supplied, both must match.', 'An array of Allocation JSON records.', 'AllocationComponent.list(requirementId, status)', 'Shared errors only.')
operation('Approve allocation', 'POST', '/api/allocations/{id}/approve', 'Allocation id in the URL; no body.', 'The Allocation JSON with status APPROVED.', 'AllocationComponent.approve(id)', '409: “Only pending allocations can be approved.”, “Not enough available stock.”, “Requirement is already covered.” or “Project has already ended.”')
operation('Issue reusable items', 'POST', '/api/allocations/{id}/issue', 'Allocation id in the URL; no body. The whole allocation is issued.', 'The Allocation JSON with status ISSUED.', 'AllocationComponent.issue(id)', '409: “Only approved reusable allocations can be issued.” or “Items can only be issued during the project period.”')
operation('Return reusable items', 'POST', '/api/allocations/{id}/return', 'Allocation id in the URL; no body. The whole issued quantity must have been received back in usable condition.', 'The Allocation JSON with status RETURNED.', 'AllocationComponent.returnItems(id)', '409: “Only issued reusable allocations can be returned.”')
operation('Record consumables used', 'POST', '/api/allocations/{id}/consume', 'Allocation id in the URL; no body. The whole allocation is consumed.', 'The Allocation JSON with status CONSUMED; the resource’s remaining stock is reduced by this quantity.', 'AllocationComponent.consume(id)', '409: “Only approved consumable allocations can be consumed.” or “Consumables can only be used during the project period.”')
operation('Cancel allocation', 'POST', '/api/allocations/{id}/cancel', 'Allocation id in the URL; no body.', 'The Allocation JSON with status CANCELLED; any reserved quantity becomes available.', 'AllocationComponent.cancel(id)', '409: “Only pending or approved allocations can be cancelled.”')
operation('Delete unused allocation', 'POST', '/api/allocations/{id}/delete', 'Allocation id in the URL; no body.', 'The deletion message.', 'AllocationComponent.delete(id)', '409: “Only pending or cancelled allocations can be deleted.”')

p('## Components and important methods')
p('Components will apply the rules and use repositories to read or save records. A list method will validate any filter, retrieve matching records, and return the JSON described above. An update or delete will first check that the record exists. Only one change to the same project or resource will be processed at a time, including changes to requirements and allocations. Related changes will be saved together or not at all.')

def comp(name, job, methods):
    p('### ' + name)
    p(job)
    for method, steps in methods:
        p('**' + method + '**')
        for i, step in enumerate(steps, 1): p(f'{i}. {step}')

comp('DepartmentComponent', 'Manages departments within the organization.', [
 ('create(name)', ['Check the name and reject duplicates.', 'Save and return the new department.']),
 ('list()', ['Retrieve and return all departments.']),
 ('update(id, name)', ['Check the new name and reject duplicates belonging to another department.', 'Save and return the department.']),
 ('delete(id)', ['Check that no project uses the department.', 'Delete it and return the deletion message.'])])
comp('ProjectComponent', 'Stores the projects and the period when resources will be used.', [
 ('create(departmentId, name, startAt, endAt)', ['Find the department and validate the name and dates.', 'Save and return the project.']),
 ('list(departmentId)', ['Return all projects, or those in the selected department.']),
 ('update(id, name, startAt, endAt)', ['Validate the supplied details. If dates change, require a future start and check for allocations other than PENDING or CANCELLED.', 'Reject date changes when such allocations exist. Otherwise save and return the update.']),
 ('delete(id)', ['Check that the project has no resource requirements.', 'Delete it and return the deletion message.'])])
comp('ResourceComponent', 'Maintains resource records and calculates what can still be allocated.', [
 ('create(name, type, totalQuantity)', ['Validate the name, type, and quantity; reject a duplicate name.', 'Save the resource and return it with its available quantity.']),
 ('list(type)', ['Retrieve all resources or filter by type.', 'Calculate availableQuantity for each and return the records.']),
 ('getAvailability(id)', ['For reusable items, subtract APPROVED and ISSUED quantities from totalQuantity. For consumables, subtract APPROVED quantities from remaining stock.', 'Return resourceId and availableQuantity.']),
 ('update(id, name, totalQuantity)', ['Validate the new name and quantity.', 'Reject a quantity below existing reservations and issued items; then save and return the record.']),
 ('delete(id)', ['Check that no requirement refers to this resource.', 'Delete it and return the deletion message.'])])
p('Approval reserves stock immediately, regardless of the project’s dates. A reservation remains until the allocation is cancelled, returned, or consumed. Future bookings that depend on an expected return are outside this small version; this keeps availability straightforward and avoids promising the same item twice.')
comp('RequirementComponent', 'Records each project’s needs and shows quantities still unallocated.', [
 ('create(projectId, resourceId, quantity)', ['Find the project and resource; validate quantity and check that the project has not ended.', 'Reject a second requirement for the same project and resource.', 'Save the requirement and return it with its allocated and shortage quantities.']),
 ('list(projectId)', ['Retrieve all requirements or those for the selected project.', 'Add approved, issued, returned, and consumed allocation quantities. Subtract that total from each requirement quantity and return the results.']),
 ('update(id, quantity)', ['Check that the project has not ended and the new quantity is positive.', 'Reject a quantity below the amount already allocated; otherwise save and return it.']),
 ('delete(id)', ['Check that no allocation refers to this requirement.', 'Delete it and return the deletion message.'])])
comp('AllocationComponent', 'Controls approval, release, return, consumption, and cancellation of assigned resources.', [
 ('create(requirementId, quantity, borrowerName, phoneNumber, smsConsent)', ['Find the requirement and check that its project has not ended. Validate the quantity and borrower details.', 'Save the allocation as PENDING with reminderAttempted false; return it. Pending requests do not reserve stock.']),
 ('list(requirementId, status)', ['Retrieve records matching the supplied filters, or all records when there are no filters.', 'Return their Allocation JSON.']),
 ('approve(id)', ['Require PENDING status and a project that has not ended.', 'Check that the quantity fits both available stock and the requirement’s remaining shortage.', 'Save status APPROVED and return the allocation.']),
 ('issue(id)', ['Require an APPROVED allocation for a REUSABLE resource, within the project period.', 'Save status ISSUED and return it. The quantity remains unavailable while with the borrower.']),
 ('returnItems(id)', ['Require an ISSUED reusable allocation and confirmation that all items were received back usable.', 'Save status RETURNED and return it. These items become available again, while the original requirement remains covered.']),
 ('consume(id)', ['Require an APPROVED allocation for a CONSUMABLE resource, within the project period.', 'Subtract its quantity from the resource’s totalQuantity and set status CONSUMED in the same save operation.', 'Return the allocation. It remains part of the fulfilled requirement.']),
 ('cancel(id)', ['Require PENDING or APPROVED status.', 'Save status CANCELLED and return it. Remove its quantity from reservations and requirement coverage.']),
 ('delete(id)', ['Require PENDING or CANCELLED status, so issued or completed records remain available.', 'Delete it and return the deletion message.'])])
comp('ReminderComponent', 'Checks reusable items due for return and requests one SMS reminder per allocation.', [
 ('checkDueReturns() scheduled every hour', ['Find ISSUED allocations whose project ends between now and 24 hours from now.', 'Keep only allocations with SMS consent, a phone number, and reminderAttempted false.', 'Mark reminderAttempted true before calling SmsComponent.sendReminder(phoneNumber, message). Include the resource name, quantity, and due time in the message.', 'Record any sending error in the application log. An attempted message is not automatically sent again. Returning or cancelling an allocation stops it from qualifying.'])])
comp('SmsComponent', 'Connects the application to Twilio through a Retrofit client.', [
 ('initialize() with @PostConstruct', ['Read the configured Twilio account details and sending number.', 'Check that the settings are present and prepare the external-service client. If settings are missing, report “SMS settings are missing.”']),
 ('sendReminder(phoneNumber, message)', ['Send the destination number and reminder text to Twilio.', 'Return whether Twilio accepted the request, or report the sending error to ReminderComponent. Acceptance does not confirm delivery.'])])

p('## Entities and repositories')
p('The following are the stored fields. Every entity has an id of type Long, generated by the database, positive, and never NULL. Input IDs must also be positive and refer to existing records. Unless marked “Yes” in the NULL column, a field must have a value. Text is trimmed before validation. JSON uses the field names shown here.')
p('Java relationships will link each Project to a Department, each ResourceRequirement to a Project and Resource, and each Allocation to a ResourceRequirement. Their JSON uses departmentId, projectId, resourceId, and requirementId to keep responses short. All dates use Philippine local time. A project period includes its start and ends just before endAt.')

def entity(name, purpose, rows, repository):
    p('### ' + name)
    p(purpose)
    p('| Field | Type | NULL | Validation |\n|---|---|---|---|\n' + '\n'.join('| ' + ' | '.join(row) + ' |' for row in rows))
    p('**' + name + 'Repository:** ' + repository)

entity('Department', 'Represents a team such as Logistics. It identifies which team owns a project.', [
 ('name', 'String', 'No', '1–100 characters; unique, ignoring letter case.')],
 'Stores and retrieves departments. Custom method: existsByNameIgnoreCase(String name), to check for a duplicate name. During an update, the current department is excluded from the duplicate check.')
entity('Project', 'Represents an organization activity with a responsible department and a period for using resources.', [
 ('department', 'Department', 'No', 'An existing department; JSON name is departmentId.'),
 ('name', 'String', 'No', '1–100 characters.'),
 ('startAt', 'LocalDateTime', 'No', 'Future time when created or when dates are changed.'),
 ('endAt', 'LocalDateTime', 'No', 'Later than startAt.')],
 'Stores and retrieves projects. Custom methods: findByDepartment_Id(Long departmentId), to list a department’s projects; existsByDepartment_Id(Long departmentId), to prevent deleting a department that still has projects.')
entity('Resource', 'Represents a pool of interchangeable usable items, such as extension cords, or consumable supplies, such as sheets of paper.', [
 ('name', 'String', 'No', '1–100 characters; unique, ignoring letter case.'),
 ('type', 'ResourceType enum', 'No', 'REUSABLE or CONSUMABLE; fixed after creation.'),
 ('totalQuantity', 'Integer', 'No', '0–1000000; cannot be below reserved or issued quantity.')],
 'Stores and retrieves resources. Custom methods: existsByNameIgnoreCase(String name), to check duplicate names; findByType(ResourceType type), to list reusable or consumable resources. The current resource is excluded from its update duplicate check.')
p('availableQuantity appears in Resource JSON but is calculated by ResourceComponent. It is not another database field.')
entity('ResourceRequirement', 'Represents one resource and the quantity needed by a project. This allows a project to list several different needs and show shortages.', [
 ('project', 'Project', 'No', 'An existing project; JSON name is projectId.'),
 ('resource', 'Resource', 'No', 'An existing resource; JSON name is resourceId.'),
 ('quantity', 'Integer', 'No', '1–1000000; at least the quantity already allocated.')],
 'Stores and retrieves project requirements. A project and resource pair must be unique. Custom methods: findByProject_Id(Long projectId), to list a project’s requirements; existsByProject_Id(Long projectId), to check whether a project can be deleted; existsByResource_Id(Long resourceId), to check whether a resource can be deleted; existsByProject_IdAndResource_Id(Long projectId, Long resourceId), to prevent duplicate requirements.')
p('allocatedQuantity and shortageQuantity appear in JSON but are calculated by RequirementComponent.')
entity('Allocation', 'Represents a quantity assigned toward a requirement and the person responsible for receiving or returning it.', [
 ('requirement', 'ResourceRequirement', 'No', 'An existing requirement; JSON name is requirementId.'),
 ('quantity', 'Integer', 'No', '1–1000000; no more than the requirement quantity. Approval must also fit stock and the remaining shortage.'),
 ('borrowerName', 'String', 'No', '1–100 characters.'),
 ('phoneNumber', 'String', 'Yes', 'If present, + followed by 8–15 digits; required when smsConsent is true.'),
 ('smsConsent', 'Boolean', 'No', 'Defaults to false; true only with the borrower’s consent.'),
 ('status', 'AllocationStatus enum', 'No', 'PENDING, APPROVED, ISSUED, RETURNED, CONSUMED, or CANCELLED; changed only by the component.'),
 ('reminderAttempted', 'Boolean', 'No', 'Defaults to false; set by ReminderComponent.')],
 'Stores and retrieves allocations. Custom methods and their parameters are listed below.')
p('**findByRequirement_Id(Long requirementId):** Lists allocations for one requirement. Used to calculate coverage and shortages, and to check allocation history before changing project dates.')
p('**findByStatus(AllocationStatus status):** Lists allocations with the selected status.')
p('**findByRequirement_IdAndStatus(Long requirementId, AllocationStatus status):** Applies both allocation list filters together.')
p('**findForResource(Long resourceId, List<AllocationStatus> statuses):** Finds reservations and issued items for a resource when calculating availability. statuses is [APPROVED, ISSUED] for reusable resources and [APPROVED] for consumables.')
p('**existsByRequirement_Id(Long requirementId):** Checks whether a requirement still has allocations before deletion.')
p('**findDueReturns(LocalDateTime from, LocalDateTime to):** Finds ISSUED allocations whose project ends in the supplied period. ReminderComponent supplies the current time and 24 hours later.')
p('findForResource and findDueReturns will use custom repository queries. Standard save, findById, findAll, and delete methods will handle basic record operations.')

text = '\n'.join(parts)
(ROOT / 'OrgResource-Concise-Submission-Proposal.md').write_text(text, encoding='utf-8')
(ROOT / 'qa' / 'readable-revision-baseline.json').write_text(json.dumps({'fullDocumentSha256': full_hash, 'entities': 5, 'operations': 25, 'status': 'proposed design only'}, indent=2))
print(json.dumps({'words': len(text.split()), 'operations': text.count('**URL:**'), 'entities': 5}))
